window.RIOT = {"generated_for": "riot.europe", "preview": false, "note": "Europe demo: landmark roll-call votes of the European Parliament plenary 2019-2026, hand-authored from the official record (HowTheyVote.eu, europarl.europa.eu) and aggregated to the national delegations. Source of truth + audit trail: data/europe/cards.json.", "n_decisions": 17, "sessions_in_table": ["EP_10", "EP_8", "EP_9"], "parties": [{"token": "DE", "name": "Germany", "color": "#1F1F1F", "logo": "assets/flags/DE.svg", "blurb": "96 seats today, elected by voters in Germany."}, {"token": "FR", "name": "France", "color": "#1F3F99", "logo": "assets/flags/FR.svg", "blurb": "81 seats today, elected by voters in France."}, {"token": "IT", "name": "Italy", "color": "#1E8A4C", "logo": "assets/flags/IT.svg", "blurb": "76 seats today, elected by voters in Italy."}, {"token": "ES", "name": "Spain", "color": "#C8102E", "logo": "assets/flags/ES.svg", "blurb": "61 seats today, elected by voters in Spain."}, {"token": "PL", "name": "Poland", "color": "#D4213D", "logo": "assets/flags/PL.svg", "blurb": "53 seats today, elected by voters in Poland."}, {"token": "RO", "name": "Romania", "color": "#E0B000", "logo": "assets/flags/RO.svg", "blurb": "33 seats today, elected by voters in Romania."}, {"token": "NL", "name": "Netherlands", "color": "#E86A10", "logo": "assets/flags/NL.svg", "blurb": "31 seats today, elected by voters in Netherlands."}, {"token": "BE", "name": "Belgium", "color": "#B8860B", "logo": "assets/flags/BE.svg", "blurb": "22 seats today, elected by voters in Belgium."}, {"token": "CZ", "name": "Czechia", "color": "#11457E", "logo": "assets/flags/CZ.svg", "blurb": "21 seats today, elected by voters in Czechia."}, {"token": "GR", "name": "Greece", "color": "#3F7FC4", "logo": "assets/flags/GR.svg", "blurb": "21 seats today, elected by voters in Greece."}, {"token": "HU", "name": "Hungary", "color": "#477050", "logo": "assets/flags/HU.svg", "blurb": "21 seats today, elected by voters in Hungary."}, {"token": "PT", "name": "Portugal", "color": "#006600", "logo": "assets/flags/PT.svg", "blurb": "21 seats today, elected by voters in Portugal."}, {"token": "SE", "name": "Sweden", "color": "#006AA7", "logo": "assets/flags/SE.svg", "blurb": "21 seats today, elected by voters in Sweden."}, {"token": "AT", "name": "Austria", "color": "#A6192E", "logo": "assets/flags/AT.svg", "blurb": "20 seats today, elected by voters in Austria."}, {"token": "BG", "name": "Bulgaria", "color": "#00966E", "logo": "assets/flags/BG.svg", "blurb": "17 seats today, elected by voters in Bulgaria."}, {"token": "DK", "name": "Denmark", "color": "#9E1B32", "logo": "assets/flags/DK.svg", "blurb": "15 seats today, elected by voters in Denmark."}, {"token": "FI", "name": "Finland", "color": "#2E5FA8", "logo": "assets/flags/FI.svg", "blurb": "15 seats today, elected by voters in Finland."}, {"token": "SK", "name": "Slovakia", "color": "#0B4EA2", "logo": "assets/flags/SK.svg", "blurb": "15 seats today, elected by voters in Slovakia."}, {"token": "IE", "name": "Ireland", "color": "#169B62", "logo": "assets/flags/IE.svg", "blurb": "14 seats today, elected by voters in Ireland."}, {"token": "HR", "name": "Croatia", "color": "#C4122F", "logo": "assets/flags/HR.svg", "blurb": "12 seats today, elected by voters in Croatia."}, {"token": "LT", "name": "Lithuania", "color": "#8A7A00", "logo": "assets/flags/LT.svg", "blurb": "11 seats today, elected by voters in Lithuania."}, {"token": "LV", "name": "Latvia", "color": "#7E2530", "logo": "assets/flags/LV.svg", "blurb": "9 seats today, elected by voters in Latvia."}, {"token": "SI", "name": "Slovenia", "color": "#2B6CB0", "logo": "assets/flags/SI.svg", "blurb": "9 seats today, elected by voters in Slovenia."}, {"token": "EE", "name": "Estonia", "color": "#0072CE", "logo": "assets/flags/EE.svg", "blurb": "7 seats today, elected by voters in Estonia."}, {"token": "CY", "name": "Cyprus", "color": "#C46A12", "logo": "assets/flags/CY.svg", "blurb": "6 seats today, elected by voters in Cyprus."}, {"token": "LU", "name": "Luxembourg", "color": "#00A1DE", "logo": "assets/flags/LU.svg", "blurb": "6 seats today, elected by voters in Luxembourg."}, {"token": "MT", "name": "Malta", "color": "#9A1B2B", "logo": "assets/flags/MT.svg", "blurb": "6 seats today, elected by voters in Malta."}], "decisions": [{"id": "EP-2019-copyright-upload-filters", "date": "2019-03-26", "session_code": "EP_8", "point": null, "organ": "European Parliament", "type": "Directive", "topic": "Internet", "headline": "Make platforms like YouTube liable for copyright-breaking uploads, and pay news publishers for their articles.", "title": "Copyright in the Digital Single Market", "raw_outcome": "Copyright in the Digital Single Market", "source_brief": "Musicians, film studios and newspapers say giant platforms make fortunes from their work while paying little. This law shifts the risk onto the platforms. Critics say the only practical way for a site to avoid liability is software that scans every upload before it goes live, and software makes mistakes.\n\n- **Upload rule (Article 13, later 17):** big platforms answer for infringing uploads unless they get licences or make **best efforts** to stop them.\n- **News rule (Article 11, later 15):** publishers get a right to be paid when platforms reuse their articles; journalists get a share. Hyperlinks and **very short extracts** stay free.\n- **What stays safe:** memes, GIFs, quotes, criticism and parody; non-commercial encyclopedias like Wikipedia and open-source code sites are exempt; young small platforms get lighter rules.\n- **The handle:** if creators deserve to be paid and platforms have dodged that for years, this finally makes them negotiate; if you fear automatic filters deleting legal posts and only the biggest firms affording the tech, this locks the internet down.", "deep_facts": "- Online content-sharing platforms become directly liable for copyright-protected content their users upload, unless they obtain authorisation (licences) or meet 'best efforts' obligations to prevent availability of notified works (Directive (EU) 2019/790, Art. 17; EP press release, 26 Mar 2019).\n- Lighter obligations apply to new platforms available for less than **three years** with annual turnover below **EUR 10 million**; they face fewer duties while their monthly unique visitors stay under **5 million** (Directive (EU) 2019/790, Art. 17(6)).\n- Non-commercial online encyclopedias (such as Wikipedia) and open-source software platforms (such as GitHub) are excluded (EP press release, 26 Mar 2019).\n- Quotation, criticism, review, caricature, parody and pastiche are protected, so memes and GIFs remain shareable (EP press release, 26 Mar 2019).\n- Press publishers gain a new right over online use of their publications; hyperlinks with individual words or very short extracts remain free, and journalists must get a share of the resulting revenue (EP press release, 26 Mar 2019; Directive (EU) 2019/790, Art. 15).\n- Member states get two years to write the rules into national law (EP press release, 26 Mar 2019).", "deep_lectura": "**Analyst read** *(inference, not stated verbatim in the record)*\n- 'Best efforts' does not say 'filter', but for a site handling millions of uploads a day there is little else that works at scale, which is why the fight was really about automated filtering.\n- Large platforms can afford licensing teams and matching software; smaller rivals past the start-up window may find compliance costs heavier, which could entrench the incumbents the law targets.\n- The news right strengthens publishers' hand in talks with search and social giants, but how much money reaches journalists depends on national deals.", "proposed_by": "European Commission (rapporteur Axel Voss)", "doc_ref": "2016/0280(COD), A8-0245/2018 (Am 271)", "outcome": "approved", "source_url": "https://www.europarl.europa.eu/doceo/document/PV-8-2019-03-26-VOT_EN.html", "curator_drop": false, "party_votes_canon": {"BE": "for", "CY": "against", "CZ": "against", "DK": "for", "EE": "against", "ES": "for", "FI": "for", "FR": "for", "GR": "for", "HR": "for", "HU": "for", "IT": "for", "LT": "for", "LU": "against", "LV": "for", "MT": "for", "NL": "against", "PL": "against", "PT": "for", "SE": "against", "SI": "against", "SK": "for"}, "tally": {"for": 348, "against": 274, "abstain": 36}}, {"id": "EP-2022-taxonomy-gas-nuclear", "date": "2022-07-06", "session_code": "EP_9", "point": null, "organ": "European Parliament", "type": "Objection", "topic": "Energy", "headline": "Block the EU from labelling some gas and nuclear power plants as green investments.", "title": "Amending the Taxonomy Climate Delegated Act and the Taxonomy Disclosures Delegated Act", "raw_outcome": "Amending the Taxonomy Climate Delegated Act and the Taxonomy Disclosures Delegated Act", "source_brief": "The EU keeps an official list of what counts as a 'green' investment, so savers and banks know what they're backing. The Commission wants to add certain gas and nuclear power plants to that list as a bridge away from coal. Voting FOR here means rejecting that addition.\n\n- **Gas gets in only if:** it replaces a dirtier coal or oil plant, gets its permit by **2030**, emits under **270 g CO2 per kWh**, and can switch to low-carbon gases by **2035**.\n- **Nuclear gets in only if:** new plants get their permit by **2045** and have a plan, money and a site to dispose of radioactive waste safely.\n- **Why it matters:** the label steers private money, so it shapes what Europe builds for decades. If Parliament does nothing, the label applies from **1 January 2023**.\n- **The handle:** if you think Europe can't quit coal or Russian gas without these plants and needs cash flowing to them, keep the label; if you think calling a fossil fuel 'green' is greenwashing that drains money from renewables, block it.", "deep_facts": "- The EU taxonomy classifies economic activities as environmentally sustainable, to steer green investment and prevent greenwashing (EP press release, 6 Jul 2022).\n- The Commission's act adds certain fossil gas and nuclear activities as 'transitional activities' contributing to climate mitigation, time-limited and subject to conditions and disclosure rules (EP press release, 6 Jul 2022; Delegated Regulation (EU) 2022/1214).\n- Gas conditions include replacing a more polluting fossil plant, a construction permit before 31 December 2030, direct emissions below 270 g CO2e/kWh, and a design allowing a full switch to renewable or low-carbon gases by the end of 2035 (Delegated Regulation (EU) 2022/1214).\n- New nuclear plants must receive construction permits before 2045 and show a plan, funds and a site for safe disposal of radioactive waste (Delegated Regulation (EU) 2022/1214).\n- Under the objection procedure, Parliament can veto only with an absolute majority of its members (**353** MEPs); if neither Parliament nor Council objects by 11 July 2022, the act applies from **1 January 2023** (EP press release, 6 Jul 2022).", "deep_lectura": "**Analyst read** *(inference, not stated verbatim in the record)*\n- The label does not ban or fund anything directly; its power is reputational and financial, deciding which projects can be sold to investors as 'sustainable'.\n- The split does not follow a simple green versus industry line: countries relying on nuclear and those needing gas to exit coal share an interest in the label, while others see the gas part as undermining the list's credibility.\n- Because vetoing needs an absolute majority rather than a simple one, the procedure is tilted toward letting the Commission's text stand.", "proposed_by": "ECON and ENVI committees (joint objection)", "doc_ref": "2022/2594(DEA), B9-0338/2022", "outcome": "rejected", "source_url": "https://howtheyvote.eu/votes/146888", "curator_drop": false, "party_votes_canon": {"AT": "for", "BE": "for", "BG": "against", "CZ": "against", "DE": "for", "DK": "for", "EE": "against", "ES": "for", "FR": "against", "HU": "against", "IE": "for", "IT": "against", "LT": "for", "LU": "for", "LV": "against", "MT": "against", "PL": "against", "PT": "for", "RO": "against", "SE": "for", "SI": "against", "SK": "against"}, "tally": {"for": 278, "against": 328, "abstain": 33}}, {"id": "EP-2023-cars-2035", "date": "2023-02-14", "session_code": "EP_9", "point": null, "organ": "European Parliament", "type": "Regulation", "topic": "Cars / climate", "headline": "End sales of new petrol and diesel cars in the EU from 2035.", "title": "CO2 emission standards for cars and vans", "raw_outcome": "CO2 emission standards for cars and vans", "source_brief": "Cars and vans are one of Europe's biggest sources of CO2. This law sets a hard date: from 2035, every new car and van sold in the EU must emit **zero CO2**, which in practice means no more new petrol or diesel models. The car you already own is not touched.\n\n- **The path:** new cars must emit **55% less** CO2 by 2030 and new vans **50% less**, compared with 2021; **100% less** in 2035.\n- **Small makers** (1,000 to 10,000 cars a year) can get an exemption until the end of 2035.\n- **Checks along the way:** the Commission reports every two years on progress toward zero-emission driving.\n- **The handle:** if you want to stop climate change and give carmakers a clear date to invest, this does it; if you worry about the price of electric cars, jobs in Europe's car industry, or rural drivers with no chargers, it may come too fast.", "deep_facts": "- Sets an EU fleet-wide target to cut CO2 from new cars and vans by **100% in 2035** compared with 2021, and intermediate 2030 targets of **55% for cars** and **50% for vans** (EP press release 20230210IPR74715).\n- Part of the 'Fit for 55' climate package; the Commission proposed it on **14 July 2021** (EP press release 20230210IPR74715).\n- By 2025 the Commission must present a method to measure CO2 over a vehicle's full life cycle; by December 2026 it must monitor the gap between official limits and real-world fuel and energy use (EP press release 20230210IPR74715).\n- Manufacturers making **1,000 to 10,000** new cars or **1,000 to 22,000** new vans a year may get a derogation until the end of 2035; those under 1,000 a year stay exempt (EP press release 20230210IPR74715).\n- The incentive rewarding makers of zero- and low-emission vehicles (0 to 50 g CO2/km) uses benchmarks of **25%** of new car sales and **17%** of new van sales for 2025 to 2029, and ends from 2030 (EP press release 20230210IPR74715).\n- In 2026 the Commission must assess progress toward the 100% targets and whether to review them, taking into account technology including plug-in hybrids and a socially fair transition (Legislative Observatory summary, 2021/0197(COD)).\n- The targets cover only new passenger cars and new vans; vehicles already on the road are not affected (follows from the regulation's scope, 'new passenger cars and new light commercial vehicles'; Legislative Observatory summary, 2021/0197(COD)).", "deep_lectura": "**Analyst read** *(inference, not stated verbatim in the record)*\n- The 2035 date is a signal to investors as much as a rule: it tells carmakers and battery plants where the market will be, which is why industry was split between those already betting on electric and those who were not.\n- The regular review clauses leave the door open to revisit the target, so the real fight over 2035 is unlikely to end with this vote.\n- The costs fall unevenly: drivers in cities with chargers adapt easily, while rural and lower-income drivers depend on how fast cheap electric cars and second-hand markets arrive.", "proposed_by": "European Commission proposal (rapporteur Jan Huitema)", "doc_ref": "2021/0197(COD), A9-0150/2022", "outcome": "approved", "source_url": "https://howtheyvote.eu/votes/152544", "curator_drop": false, "party_votes_canon": {"BE": "for", "BG": "for", "CY": "for", "CZ": "against", "DK": "for", "EE": "for", "ES": "for", "FI": "for", "FR": "for", "GR": "for", "HR": "against", "HU": "against", "IE": "for", "IT": "against", "LT": "for", "LU": "for", "MT": "for", "NL": "for", "PL": "against", "PT": "for", "SE": "for", "SK": "for"}, "tally": {"for": 340, "against": 279, "abstain": 21}}, {"id": "EP-2023-carbon-price-heating-fuel", "date": "2023-04-18", "session_code": "EP_9", "point": null, "organ": "European Parliament", "type": "Directive", "topic": "Climate", "headline": "Put a carbon price on home heating and road fuel from 2027.", "title": "Revision of the EU Emissions Trading System", "raw_outcome": "Revision of the EU Emissions Trading System", "source_brief": "Today factories and power plants pay for their CO2 in the EU carbon market. This reform creates a **second carbon market** for fuel used to heat buildings and drive on roads from **2027**, so the cost of heating oil, gas and petrol reflects its emissions.\n\n- **Heavy industry too:** its free pollution permits are phased out between **2026 and 2034**, and its emissions must fall **62%** by 2030 compared with 2005.\n- **Brakes built in:** if the price tops **€45** for two months in a row, extra permits are released; the start can slip a year if energy prices are exceptionally high.\n- **The cushion:** money from the new market feeds a **Social Climate Fund** of up to **€65 billion** for vulnerable households, small firms and transport users.\n- **The handle:** if a price on pollution is the fairest way to cut emissions, with help for those who struggle, this is overdue; if you think families should not pay more to heat their homes and drive to work, this reaches straight into their bills.", "deep_facts": "- A separate new emissions trading system (ETS II) for fuel used in buildings and road transport, and some other sectors, will put a price on their emissions from **2027**, or **2028** if energy prices are exceptionally high (EP press release, 18 Apr 2023; OEIL summary).\n- If the average ETS II price exceeds **€45** for two consecutive months, **20 million** allowances are released from the market stability reserve (OEIL summary).\n- In the existing carbon market, emissions must fall **62%** by 2030 compared with 2005, and free allowances to companies are phased out from **2026 until 2034** (EP press release, 18 Apr 2023).\n- Member states with a national carbon tax at least as high as the ETS II price may exempt fuel suppliers until December 2030 (OEIL summary).\n- All national revenues from auctioning allowances must be spent on climate-related activities (OEIL summary).\n- A companion Social Climate Fund, funded from ETS II auctions up to **€65 billion** plus 25% national money (about **€86.7 billion** in total), supports vulnerable households, micro-enterprises and transport users (EP press release, 18 Apr 2023).\n- The package is part of 'Fit for 55', the EU plan to cut greenhouse gas emissions by at least 55% by 2030 compared with 1990 (EP press release, 18 Apr 2023).", "deep_lectura": "**Analyst read** *(inference, not stated verbatim in the record)*\n- Pricing carbon at the pump and the boiler is the first time the EU carbon market reaches households directly rather than through industry, which makes it far more visible politically.\n- The €45 price brake and the 2028 escape hatch show the drafters expected a backlash over bills and tried to cap it in advance.\n- The Social Climate Fund is the political glue: whether it reaches the right people in time decides whether this feels like climate policy or a new tax.", "proposed_by": "European Commission (rapporteur Peter Liese)", "doc_ref": "2021/0211A(COD), A9-0162/2022, Am 680", "outcome": "approved", "source_url": "https://howtheyvote.eu/votes/154173", "curator_drop": false, "party_votes_canon": {"AT": "for", "BE": "for", "BG": "abstain", "CY": "against", "DE": "for", "DK": "for", "EE": "for", "ES": "for", "FI": "for", "GR": "for", "HR": "for", "HU": "against", "IE": "for", "LT": "for", "LU": "for", "LV": "for", "MT": "for", "NL": "for", "PT": "for", "RO": "for", "SE": "for", "SI": "for", "SK": "for"}, "tally": {"for": 413, "against": 167, "abstain": 57}}, {"id": "EP-2024-nature-restoration", "date": "2024-02-27", "session_code": "EP_9", "point": null, "organ": "European Parliament", "type": "Regulation", "topic": "Nature", "headline": "Set binding EU targets to restore damaged nature: 20% of land and sea by 2030.", "title": "Nature restoration", "raw_outcome": "Nature restoration", "source_brief": "Europe's own figures say **over 80%** of its habitats are in poor shape. This law turns 'protect what's left' into 'fix what's broken', with binding targets for every country. The fight is over land: the same fields, bogs and riverbanks that would be restored are where people farm and build.\n\n- **The targets:** restore **30%** of habitats in poor condition by 2030, **60%** by 2040, **90%** by 2050.\n- **What you'd see:** **3 billion** extra trees, **25,000 km** of rivers freed from barriers, no net loss of city green space.\n- **The farm question:** drained peatlands must be restored (at least **30%** by 2030), but rewetting stays **voluntary** for farmers and landowners, and farm targets can be paused if food supply is at risk.\n- **The handle:** if collapsing nature is the long-term threat to food, water and climate, binding targets are overdue; if you think farmers already carry too many EU rules and land is for producing food, this is one more burden from Brussels.", "deep_facts": "- As an EU-wide target that countries meet jointly through national restoration plans, restoration measures must cover at least **20%** of the EU's land areas and at least **20%** of its sea areas by **2030**, and all ecosystems in need of restoration by **2050** (text put to the vote, 27 Feb 2024; EP press material).\n- Habitats in poor condition must be brought to good condition: at least **30%** by 2030, **60%** by 2040, **90%** by 2050 (EP press material).\n- Farmland: countries must show progress on two of three indicators (grassland butterfly index, share of farmland with high-diversity landscape features, organic carbon in cropland soil) and take measures to raise the common farmland bird index (EP press material).\n- Drained peatlands: restore at least **30%** by 2030 (at least a quarter rewetted), **40%** by 2040, **50%** by 2050 (at least a third rewetted); rewetting remains voluntary for farmers and private landowners (EP press material).\n- An emergency brake lets the farmland targets be suspended in exceptional circumstances if they severely reduce the land needed for sufficient food production (EP press material).\n- Further targets: **3 billion** additional trees, at least **25,000 km** of rivers restored to free-flowing, no net loss of urban green space and tree canopy (EP press material).\n- Over **80%** of European habitats are assessed as being in poor shape (EP press material; HowTheyVote 164499).", "deep_lectura": "**Analyst read** *(inference, not stated verbatim in the record)*\n- The real weight sits in the national plans each country must write: the law sets percentages, but where and how restoration happens is left to governments, so the practical bite depends on 27 capitals.\n- The voluntary rewetting clause and the food-security brake were concessions to make the law passable; critics on one side say they hollow it out, critics on the other say the brake is too hard to pull.\n- The vote became a proxy for a wider mood about green rules and farmer protests, so it is also a test of how far the EU's climate and nature agenda can go.", "proposed_by": "European Commission (rapporteur César Luena)", "doc_ref": "2022/0195(COD), A9-0220/2023", "outcome": "approved", "source_url": "https://howtheyvote.eu/votes/164499", "curator_drop": false, "party_votes_canon": {"AT": "for", "BG": "against", "CY": "for", "DK": "for", "EE": "for", "FI": "for", "FR": "for", "HU": "for", "IE": "for", "IT": "against", "LU": "for", "LV": "for", "MT": "for", "PL": "against", "PT": "for", "RO": "against", "SI": "for", "SK": "for"}, "tally": {"for": 329, "against": 275, "abstain": 24}}, {"id": "EP-2024-ai-act", "date": "2024-03-13", "session_code": "EP_9", "point": null, "organ": "European Parliament", "type": "Regulation", "topic": "Tech / AI", "headline": "Adopt the EU AI Act: ban social scoring, strict rules for AI in hiring and policing.", "title": "Artificial Intelligence Act", "raw_outcome": "Artificial Intelligence Act", "source_brief": "AI is already deciding who gets a job interview, a loan or a police check. This law sorts AI by how risky it is: the most dangerous uses are banned, risky ones must follow strict rules, and everyday tools are mostly left alone.\n\n- **Banned:** social scoring, AI that manipulates people or exploits their weaknesses, **emotion recognition at work and school**, and scraping faces from the internet or CCTV to build databases.\n- **Strict rules** for AI in hiring, education, banking, health, borders and courts: human oversight, logs, and a **right to an explanation**.\n- **Police facial recognition** in public is banned in principle, but allowed in listed cases (e.g. searching for a missing person, stopping a terror attack) with prior approval.\n- **The handle:** if you want your rights protected before AI spreads everywhere, this is a world first; if you think it will slow European innovation while US and Chinese firms race ahead, or that the police loopholes are too wide, vote against.", "deep_facts": "- Sets obligations for AI based on its potential risks and level of impact (EP press release 20240308IPR19015).\n- Bans biometric categorisation based on sensitive characteristics, untargeted scraping of facial images from the internet or CCTV, emotion recognition in the workplace and schools, social scoring, predictive policing based solely on profiling, and AI that manipulates behaviour or exploits vulnerabilities (EP press release 20240308IPR19015).\n- Remote biometric identification by law enforcement is prohibited in principle, except in exhaustively listed situations; real-time use needs strict safeguards, limits in time and place, and prior judicial or administrative authorisation, e.g. a targeted search for a missing person or preventing a terrorist attack (EP press release 20240308IPR19015).\n- High-risk uses (critical infrastructure, education, employment, essential services such as healthcare and banking, some law enforcement, migration and border management, justice and elections) must assess and reduce risks, keep logs, be transparent and accurate, and ensure human oversight; citizens can complain and get explanations (EP press release 20240308IPR19015).\n- General-purpose AI models must meet transparency duties, including EU copyright compliance and detailed summaries of training content; the most powerful face extra evaluations and incident reporting; deepfakes must be labelled (EP press release 20240308IPR19015).\n- Fines for banned practices reach up to **€35 million** or **7%** of worldwide annual turnover, whichever is higher (Regulation (EU) 2024/1689, Art. 99).\n- Bans apply 6 months after entry into force, general-purpose AI rules after 12 months, most rules after 24 months, high-risk obligations after 36 months (EP press release 20240308IPR19015).", "deep_lectura": "**Analyst read** *(inference, not stated verbatim in the record)*\n- The EU is betting on the 'Brussels effect': global firms tend to build one product to EU rules rather than two, so this law may shape AI far beyond Europe.\n- The police exceptions were the price of a deal with national governments; critics on civil liberties see them as the crack that lets mass surveillance in later.\n- Much depends on detail still to come (standards, codes of practice, national enforcers), so the real strictness of the law will only show when it is applied.", "proposed_by": "European Commission proposal (co-rapporteurs Brando Benifei and Dragoş Tudorache)", "doc_ref": "2021/0106(COD), A9-0188/2023", "outcome": "approved", "source_url": "https://howtheyvote.eu/votes/166051", "curator_drop": false, "party_votes_canon": {"AT": "for", "BE": "for", "BG": "for", "CY": "for", "CZ": "for", "DE": "for", "DK": "for", "EE": "for", "ES": "for", "FI": "for", "FR": "for", "GR": "for", "HR": "for", "HU": "for", "IE": "for", "IT": "for", "LT": "for", "LU": "for", "LV": "for", "MT": "for", "NL": "for", "PL": "for", "PT": "for", "RO": "for", "SE": "for", "SI": "for", "SK": "for"}, "tally": {"for": 523, "against": 46, "abstain": 49}}, {"id": "EP-2024-migration-pact-solidarity", "date": "2024-04-10", "session_code": "EP_9", "point": null, "organ": "European Parliament", "type": "Regulation", "topic": "Migration", "headline": "Make every EU country help arrival states with asylum seekers: take some in, or pay.", "title": "Asylum and migration management", "raw_outcome": "Asylum and migration management", "source_brief": "For years, the countries on the EU's edge (Italy, Greece, Spain, Malta) have handled most asylum seekers, while others refused to share. This law rewrites who is responsible for each asylum request and makes help from the rest of the EU compulsory, but lets each country choose how to help.\n\n- **First arrival still counts:** people must apply in the EU country they **enter first** (or where they already legally live); they cannot pick the country.\n- **'Mandatory solidarity':** each year at least **30,000 relocations** and **€600 million** in contributions are planned EU-wide; a country can take people in, **pay about €20,000 per person** it doesn't take, or send staff and equipment.\n- **Fair shares:** each country's share is set **half by population, half by wealth (GDP)**.\n- **The handle:** if you want order at the borders and fair sharing between countries, this is the first deal in years that does both; if you think rich countries can now buy their way out of taking refugees, or that it still leaves border countries (and asylum seekers) stuck, vote against.", "deep_facts": "- Replaces the Dublin regulation's rules on which member state examines an asylum application; applicants should apply in the member state of **first entry** or legal residence, and have no choice over which country examines their claim or where they are relocated (Legislative Observatory summary, 2020/0279(COD)).\n- Creates an **Annual Solidarity Pool**, proposed each year by the Commission, of at least **30,000 relocations** and **€600 million** in financial contributions EU-wide (Legislative Observatory summary, 2020/0279(COD)).\n- Each member state's share is based **50% on population and 50% on GDP** (Legislative Observatory summary, 2020/0279(COD)).\n- Member states choose how to contribute: relocating applicants, making financial contributions, or providing operational and technical support (EP press release 20240408IPR20290); the reference amount of **€20,000 per person** not relocated is not in the Parliament's summary or first-reading text; it comes from the final Regulation (EU) 2024/1351 as reported by the IRC and Wikipedia.\n- If relocation pledges fall short, a country can be asked to take responsibility for examining applications of people it would otherwise send back to a benefitting country (Legislative Observatory summary, 2020/0279(COD)).\n- New responsibility criteria: a diploma under six years old from an EU country makes that country responsible; family-reunion criteria are widened (Legislative Observatory summary, 2020/0279(COD)).\n- Countries receiving recurring arrivals from sea rescues get an indicative share of the pool, with vulnerable people, including unaccompanied minors, considered for relocation; the Commission appoints an EU Solidarity Coordinator (Legislative Observatory summary, 2020/0279(COD)).", "deep_lectura": "**Analyst read** *(inference, not stated verbatim in the record)*\n- The flexibility is the whole deal: letting countries pay instead of hosting was the price of getting reluctant governments on board, and it lets them tell voters they took no one.\n- Keeping the first-entry rule largely intact means the countries on the EU's outer border still carry the first burden; solidarity softens it rather than replaces it.\n- Opposition comes from opposite directions: some see it as too harsh on asylum seekers, others as forcing migrants or payments on unwilling countries. That cross-pressure is why a deal took years.", "proposed_by": "European Commission proposal (rapporteur Tomas Tobé)", "doc_ref": "2020/0279(COD), A9-0152/2023", "outcome": "approved", "source_url": "https://howtheyvote.eu/votes/167531", "curator_drop": false, "party_votes_canon": {"AT": "for", "BG": "for", "CY": "for", "CZ": "against", "DK": "for", "EE": "for", "ES": "for", "FI": "for", "FR": "against", "HR": "for", "HU": "against", "IE": "for", "IT": "against", "LT": "for", "LU": "for", "LV": "for", "MT": "abstain", "NL": "for", "PL": "against", "PT": "for", "RO": "for", "SE": "for", "SI": "for", "SK": "against"}, "tally": {"for": 322, "against": 266, "abstain": 31}}, {"id": "EP-2024-abortion-charter", "date": "2024-04-11", "session_code": "EP_9", "point": null, "organ": "European Parliament", "type": "Resolution", "topic": "Abortion", "headline": "Call for the EU's rights charter to include a right to safe, legal abortion.", "title": "Inclusion of the right to abortion in the EU Charter of Fundamental Rights", "raw_outcome": "Inclusion of the right to abortion in the EU Charter of Fundamental Rights", "source_brief": "A resolution asks EU leaders to reopen the EU Treaties and add access to safe and legal abortion to the EU Charter of Fundamental Rights. It is a political call: it changes no law by itself, and changing the Charter would need **every EU country** to agree.\n\n- **The new line:** Article 3 would say everyone has a right to bodily autonomy and to sexual and reproductive healthcare, **including access to safe and legal abortion**.\n- **Countries named:** it urges all EU countries to fully decriminalise abortion, asks **Poland and Malta** to repeal their bans and restrictions, and wants abortion taught in medical training.\n- **Money and doctors:** it asks that **no EU funding** go to organisations it sees as working against women's rights, including reproductive rights, and criticises doctors and hospitals refusing abortion on grounds of **conscience**.\n- **The handle:** if you see access to abortion as a basic right that should not depend on which country you live in, this sets a floor for all of Europe; if you think health care and a question of deep moral conviction belong to each country and its voters, or that conscience rights deserve protection, this reaches too far.", "deep_facts": "- The resolution urges the European Council to launch a Convention to revise the Treaties and add sexual and reproductive healthcare and the right to safe and legal abortion to the Charter, as a new **Article 3(2a)** (B9-0205/2024, para. 3).\n- Proposed wording: 'Everyone has the right to bodily autonomy, to free, informed, full and universal access to sexual and reproductive health and rights, and to all related healthcare services without discrimination, including access to safe and legal abortion' (B9-0205/2024, para. 3).\n- Health care, including sexual and reproductive health, is a **national power**; changing the Charter would need **unanimous agreement** of all member states (European Parliament press release 20240408IPR20314, 11 Apr 2024).\n- It urges member states to fully decriminalise abortion in line with the 2022 WHO guidelines, calls on **Poland and Malta** to repeal their bans and restrictions, and asks that abortion methods be an obligatory part of medical training (B9-0205/2024, paras. 6 and 11).\n- It asks the Commission to ensure organisations 'working against gender equality and women's rights including reproductive rights' receive **no EU funding**, and asks governments to raise spending on family planning services (B9-0205/2024, paras. 5 and 10).\n- It condemns abortion being refused by doctors, and sometimes whole institutions, under the 'conscience' clause, especially where delay endangers the patient (B9-0205/2024, para. 8).\n- Context cited in the text: on 4 March 2024 France became the first country to write the freedom to have an abortion into its constitution (B9-0205/2024, recital H).", "deep_lectura": "**Analyst read** *(inference, not stated verbatim in the record)*\n- Because a Charter change needs every government to agree, the practical effect is a signal of the Parliament's position rather than a step with a clear route to becoming law.\n- The vote bundles several questions into one: an EU-level right, pressure on named countries, EU funding rules and doctors' conscience clauses. Someone can agree with one part and reject another, which a single yes or no hides.\n- The underlying tension is who decides: an EU-wide rights standard versus each country setting its own rules on a morally contested question.", "proposed_by": "Motion tabled by MEPs on behalf of the S&D, Renew, Greens/EFA and The Left groups, with five further MEPs as co-signatories", "doc_ref": "2024/2655(RSP), B9-0205/2024", "outcome": "approved", "source_url": "https://howtheyvote.eu/votes/168054", "curator_drop": false, "party_votes_canon": {"AT": "for", "BE": "for", "BG": "for", "CY": "for", "CZ": "for", "DE": "for", "DK": "for", "EE": "for", "ES": "for", "FI": "for", "FR": "for", "GR": "for", "HR": "for", "HU": "against", "IE": "for", "IT": "against", "LU": "for", "MT": "against", "NL": "for", "PL": "against", "PT": "for", "RO": "for", "SE": "for", "SI": "for"}, "tally": {"for": 336, "against": 163, "abstain": 39}}, {"id": "EP-2024-ukraine-strikes-inside-russia", "date": "2024-09-19", "session_code": "EP_10", "point": null, "organ": "European Parliament", "type": "Resolution", "topic": "Ukraine war", "headline": "Urge EU countries to let Ukraine hit military targets inside Russia with Western weapons.", "title": "Continued financial and military support to Ukraine by EU Member States", "raw_outcome": "Continued financial and military support to Ukraine by EU Member States", "source_brief": "Several Western countries send Ukraine weapons on condition they are not fired at Russian soil. This paragraph of a Parliament resolution calls on them to drop that condition **immediately** for legitimate military targets.\n\n- **Why now:** since late August Russia has run its heaviest air campaign of the war, and Ukraine can hit the launch sites only with limits on what it may use.\n- **What it is not:** a resolution is a political call, not a law; each government still decides what its own weapons may be used for.\n- **The case for:** under the UN Charter a country under attack may defend itself, and the text says the limits leave Ukraine's people exposed.\n- **The handle:** if you see the limits as tying Ukraine's hands while Russia strikes freely, lift them; if you fear Western weapons hitting Russia pulls Europe closer to direct war with a nuclear power, keep them.", "deep_facts": "- Paragraph 8 'calls on the Member States to immediately lift restrictions on the use of Western weapons systems delivered to Ukraine against legitimate military targets on Russian territory', arguing the restrictions hinder Ukraine's right to self-defence and leave it exposed to attacks on its population and infrastructure (RC-B10-0028/2024, §8).\n- The resolution recalls Ukraine's right to self-defence under Article 51 of the UN Charter (RC-B10-0028/2024, §7).\n- Since 24 August 2024 Russia has carried out its most intense aerial bombardment campaign yet, and has damaged or destroyed up to **80%** of Ukraine's energy infrastructure (RC-B10-0028/2024, recital E).\n- The resolution notes Iran's transfer of close-range ballistic missiles to Russia and reports of Chinese military assistance (RC-B10-0028/2024, recital K).\n- The same resolution also asks for faster deliveries of air defence and ammunition, including Taurus missiles (RC-B10-0028/2024, §9).\n- Parliament voted on paragraph 8 separately, so FOR keeps the call in the resolution and AGAINST removes it (HowTheyVote 169642, vote on § 8).", "deep_lectura": "**Analyst read** *(inference, not stated verbatim in the record)*\n- Parliament has no say over any country's weapons, so the paragraph is a signal aimed at the capitals that still hold back, and at Moscow.\n- Keeping or cutting a single sentence lets members back Ukraine overall while drawing their own line on escalation.\n- 'Legitimate military targets' does real work: it frames the strikes as lawful self-defence and leaves the hard question (what counts) to governments.", "proposed_by": "Joint motion for a resolution (RC-B10-0028/2024)", "doc_ref": "2024/2799(RSP), RC-B10-0028/2024, §8", "outcome": "approved", "source_url": "https://howtheyvote.eu/votes/169642", "curator_drop": false, "party_votes_canon": {"BE": "for", "BG": "for", "DE": "for", "DK": "for", "EE": "for", "ES": "for", "FI": "for", "GR": "for", "HR": "for", "IE": "abstain", "IT": "against", "LT": "for", "LU": "for", "LV": "for", "MT": "against", "NL": "for", "PL": "for", "PT": "for", "RO": "for", "SE": "for", "SI": "for"}, "tally": {"for": 377, "against": 191, "abstain": 51}}, {"id": "EP-2025-rearm-europe", "date": "2025-03-12", "session_code": "EP_10", "point": null, "organ": "European Parliament", "type": "Resolution", "topic": "Defence", "headline": "Back rearming Europe: at least 3% of GDP on defence, more weapons for Ukraine.", "title": "The white paper on the future of European defence", "raw_outcome": "The white paper on the future of European defence", "source_brief": "With the US signalling it may step back from Ukraine and from European security, this text sets out where the Parliament stands before the Commission publishes its big defence plan. It changes no law by itself, but it is a loud political signal: Europe should spend much more on weapons, faster, and together.\n\n- **The money:** it welcomes the Commission's five-point ReArm Europe plan (which the Commission says could raise up to **€800 billion**), asks every EU country to spend **at least 3% of GDP** on defence, and wants new ways to pay now, such as exploring **European defence bonds**, instead of waiting for the next EU budget.\n- **Ukraine:** more arms and ammunition, and it asks allies to lift **all limits** on Ukraine using Western weapons against military targets **inside Russia**.\n- **Who decides:** defence decisions would move from **unanimity to majority voting** (except military operations), so one country could no longer block.\n- **The handle:** if Russia is the biggest threat since the Cold War and the US can no longer be relied on, rearming is the price of peace; if you fear an arms race, more EU debt, or money taken from schools and hospitals, this is the moment to say no.", "deep_facts": "- The resolution states that \"Europe is today facing the most profound military threat to its territorial integrity since the end of the Cold War\" and calls Russia, supported by Belarus, China, North Korea and Iran, \"the most significant direct and indirect threat against the EU\" (EP press release 20250310IPR27230).\n- It asks that the upcoming White Paper put forward measures so that \"truly groundbreaking and necessary efforts\" can be made, and that the EU coordinate joint responses \"similar to those used in wartime\" (resolution RC-B10-0146/2025, paras 9 and 10). It \"welcomes the five-point 'ReArm Europe' plan proposed by the Commission President on 4 March 2025\" (para 68).\n- It says member states must raise defence spending to **at least 3% of GDP**, noting that some already spend 5% (para 69).\n- The ReArm Europe plan, announced by Commission President von der Leyen on **4 March 2025**, aims to mobilise up to **€800 billion**, including a new loan instrument of up to **€150 billion** and relaxed EU deficit rules for defence spending (European Commission statement 25/673, 4 March 2025).\n- It calls on member states, partners and NATO allies to lift all restrictions on the use of Western weapons delivered to Ukraine against military targets on Russian territory (EP press release 20250310IPR27230).\n- It notes that recent actions and statements by the Trump administration raised concerns about the US stance on Russia, NATO and European security, and condemns US threats against Greenland (EP press release 20250310IPR27230).\n- It backs a council of defence ministers, a move from unanimity to qualified majority for EU defence decisions (except military operations with an executive mandate), more common procurement, and a European pillar in NATO able to act autonomously (EP press release 20250310IPR27230; resolution para 58).\n- It says \"urgent needs cannot wait for the next multiannual financial framework\" and asks for innovative funding solutions without delay (para 67); it calls for a system of **European defence bonds** to be explored, plus using unused 'coronabonds' for defence (para 73). It is a non-binding resolution (procedure 2025/2565(RSP)).", "deep_lectura": "**Analyst read** *(inference, not stated verbatim in the record)*\n- The text is less about the White Paper itself than about positioning: the Parliament wants a say in a field where national governments and the Commission hold the real levers, and uses a sweeping resolution to stake its claim early.\n- Ending unanimity on defence is the sleeper item: it would stop a single government from vetoing EU defence decisions, which shifts power from capitals to Brussels far beyond this crisis.\n- Joint 'defence bonds' would extend the post-COVID precedent of shared EU borrowing, a line that frugal and sovereignty-minded voters fought hard to keep exceptional.", "proposed_by": "Joint motion for a resolution tabled by several political groups", "doc_ref": "RC-B10-0146/2025/REV1 (procedure 2025/2565(RSP))", "outcome": "approved", "source_url": "https://howtheyvote.eu/votes/172867", "curator_drop": false, "party_votes_canon": {"AT": "for", "BE": "for", "BG": "for", "CY": "for", "CZ": "against", "DE": "for", "DK": "for", "EE": "for", "ES": "for", "FI": "for", "FR": "against", "HR": "for", "HU": "against", "IE": "for", "IT": "for", "LT": "for", "LU": "for", "LV": "for", "MT": "against", "NL": "for", "PT": "for", "RO": "for", "SE": "for", "SI": "for"}, "tally": {"for": 419, "against": 204, "abstain": 46}}, {"id": "EP-2025-wolf-protection", "date": "2025-05-08", "session_code": "EP_10", "point": null, "organ": "European Parliament", "type": "Directive", "topic": "Wildlife", "headline": "Downgrade the wolf from 'strictly protected' to 'protected', making culling easier.", "title": "The protection status of the wolf (Canis lupus)", "raw_outcome": "The protection status of the wolf (Canis lupus)", "source_brief": "Wolves were nearly wiped out in much of Europe; under strict EU protection they have come back, now **over 20,000**, with numbers and range still growing. In some regions that means attacks on sheep and cattle. This change loosens the rules so governments can manage packs more freely.\n\n- **What changes:** the wolf moves from 'strictly protected' to 'protected' in EU nature law, matching a change already made in the Bern Convention, Europe's wildlife treaty.\n- **What doesn't:** countries must still keep wolf populations healthy, and any country can keep strict protection at home.\n- **The speed:** fast-tracked, with no amendments to the Commission's text.\n- **The handle:** if you think a recovered species should be managed like other wildlife and rural livelihoods matter, lower the protection; if you think the comeback is fragile and the answer is fences, dogs and compensation rather than shooting, keep it strict.", "deep_facts": "- The Habitats Directive is amended so the wolf changes from 'strictly protected' to 'protected' status, aligning EU law with the Bern Convention (EP press releases, 5 and 8 May 2025).\n- The Bern Convention change followed an EU request and entered into force on **7 March 2025** (Council of the EU, 16 Apr 2025).\n- The Commission cites over **20,000** wolves in Europe, with populations and ranges growing, and increasing conflicts with human activities in some regions, in particular concerning livestock (EP press release, 8 May 2025).\n- Member states must continue to ensure the wolf's favourable conservation status, and may still list it as strictly protected in national law or keep stricter measures (EP press release, 8 May 2025).\n- Parliament handled the file under its urgent procedure; the Council had already endorsed the same text on 16 April 2025 (EP press release, 8 May 2025).\n- The change applies 20 days after publication in the Official Journal, with **18 months** for member states to comply (EP press release, 8 May 2025).", "deep_lectura": "**Analyst read** *(inference, not stated verbatim in the record)*\n- The wolf has become a symbol in a broader rural backlash against EU green rules; the vote carries meaning beyond the species itself.\n- Downgrading does not order culls: the practical effect depends on each country, so outcomes may diverge sharply between regions.\n- Fast-tracking without amendments limited debate on prevention and compensation, which conservationists see as the real fix and farmers see as insufficient.", "proposed_by": "European Commission", "doc_ref": "C10-0044/2025", "outcome": "approved", "source_url": "https://howtheyvote.eu/votes/176241", "curator_drop": false, "party_votes_canon": {"AT": "for", "BE": "for", "BG": "for", "CY": "for", "CZ": "for", "DE": "for", "DK": "for", "EE": "for", "ES": "for", "FR": "for", "GR": "for", "HR": "for", "HU": "for", "IE": "for", "LT": "for", "LU": "for", "LV": "for", "MT": "for", "NL": "for", "PL": "for", "PT": "against", "RO": "for", "SE": "for", "SK": "against"}, "tally": {"for": 371, "against": 162, "abstain": 37}}, {"id": "EP-2025-censure-von-der-leyen", "date": "2025-07-10", "session_code": "EP_10", "point": null, "organ": "European Parliament", "type": "Motion of censure", "topic": "Institutions", "headline": "Sack von der Leyen's whole Commission over her secret Pfizer texts and other complaints.", "title": "Of censure on the Commission", "raw_outcome": "Of censure on the Commission", "source_brief": "The Parliament has one nuclear button over the EU's government: it can sack the entire Commission at once. This motion presses it. Voting **for** means the Commission, President von der Leyen included, must resign; voting **against** keeps it in office.\n\n- **The main charge:** during COVID, von der Leyen swapped text messages with Pfizer's chief executive while the EU bought vaccines; on 14 May 2025 an EU court **annulled** the Commission's refusal to release them.\n- **Other complaints:** weak checks on post-COVID recovery money (citing the EU's auditors), using an emergency treaty article for a **€150 billion** defence loan plan, and alleged interference in elections in Romania and Germany through the Digital Services Act.\n- **It's all or nothing:** the motion cannot remove just one person; all commissioners go.\n- **The handle:** if you think leaders who dodge transparency must face real consequences, this is the only tool that bites; if you think toppling the EU's government while war goes on in Ukraine causes chaos for grievances better handled by courts, vote against.", "deep_facts": "- A motion of censure, if adopted, obliges the members of the Commission to resign as a body (Treaty on the Functioning of the EU, Art. 234; EPRS briefing 'Motion of censure', 12.9.2024).\n- Adoption needs a **two-thirds majority of votes cast**, representing a **majority of all MEPs**; tabling it needs **one tenth** of MEPs, i.e. **72** (EP press release 20250704IPR29455).\n- The motion cites the Commission's refusal to disclose text messages exchanged between von der Leyen and Pfizer's chief executive from 1 January 2021 to 11 May 2022; on 14 May 2025 the General Court (Case T-36/23) annulled that refusal, finding the Commission gave no plausible explanation for not holding them (motion B10-0319/2025, recitals and point E).\n- It notes the EU spent **€35 billion** on COVID-19 vaccines, with **€4 billion** of doses unused, and an ongoing European Public Prosecutor's Office investigation opened in 2022 into the Pfizer contracts (motion, points A and D).\n- It cites the Court of Auditors' Special Report 22/2024 on weak controls and risks of double funding in the post-COVID Recovery and Resilience Facility (motion, points F and G).\n- It calls the use of Article 122 TFEU (an emergency clause) as the legal basis for SAFE, a **€150 billion** defence financing plan, an abuse of competence (motion, points I, J and 3).\n- It accuses the Commission of interfering in elections in Romania and Germany through a distorted use of the Digital Services Act (motion, point K and 2).\n- The plenary debate with von der Leyen took place on Monday 7 July 2025 (EP press release 20250704IPR29455).\n", "deep_lectura": "**Analyst read** *(inference, not stated verbatim in the record)*\n- The very high threshold means such motions work mostly as a stage: they force a public debate and a recorded vote that pins each MEP to a position on the Commission.\n- The Pfizer texts have become a symbol of a wider complaint about how centralised and opaque decision-making has become around the Commission President, a complaint shared well beyond the motion's backers.\n- Voting against is not necessarily an endorsement of the Commission; for many it is a judgement that the remedy (removing everyone) is out of proportion to the charges.", "proposed_by": "Gheorghe Piperea and other MEPs (at least 72 signatories)", "doc_ref": "B10-0319/2025 (procedure 2025/2140(INS))", "outcome": "rejected", "source_url": "https://howtheyvote.eu/votes/178149", "curator_drop": false, "party_votes_canon": {"AT": "against", "BE": "against", "BG": "against", "CZ": "for", "DE": "against", "DK": "against", "EE": "against", "ES": "against", "FI": "against", "GR": "against", "HR": "against", "HU": "for", "IT": "against", "LT": "against", "LU": "against", "LV": "against", "MT": "against", "NL": "against", "PT": "against", "SE": "against", "SI": "against"}, "tally": {"for": 175, "against": 360, "abstain": 18}}, {"id": "EP-2025-gaza-israel-palestine", "date": "2025-09-11", "session_code": "EP_10", "point": null, "organ": "European Parliament", "type": "Resolution", "topic": "Middle East", "headline": "Call for a Gaza ceasefire, freed hostages, aid access and a partial EU-Israel trade suspension.", "title": "Gaza at breaking point: EU action to combat famine and the urgent need to release hostages and move towards a two-state solution", "raw_outcome": "Gaza at breaking point: EU action to combat famine and the urgent need to release hostages and move towards a two-state solution", "source_brief": "A resolution sets out what the Parliament wants the EU to do about the war in Gaza, putting demands on Israel, Hamas and EU governments at once. It is a political call: it changes no law and suspends nothing by itself.\n\n- **Hostages and ceasefire:** an immediate, permanent ceasefire, the **unconditional release of all hostages** held in Gaza, new EU sanctions on **Hamas**, and no role for Hamas in governing Gaza.\n- **Aid and Israel:** it condemns the Israeli government for blocking aid, which it links to famine in northern Gaza, and backs the Commission's proposal to **partly suspend the trade side** of the EU-Israel Association Agreement, plus sanctions on two Israeli ministers.\n- **The long run:** a two-state solution on the 1967 borders, a reformed **Palestinian Authority** governing Gaza, and EU countries asked to **consider recognising** a Palestinian state. It also reaffirms Israel's right to self-defence within international law.\n- **The handle:** if you think the EU must use its trade weight to get aid in and push toward two states, while still pressing Hamas on the hostages, this does that; if you think pressuring Israel and talking of recognition while hostages are still held rewards Hamas, or instead that 'consider' and 'partial' are too timid, this is not the text for you.", "deep_facts": "- Context in the text: Hamas's attack of 7 October 2023 killed **1,200** people and took **250** hostages; about **48** hostages remain, around 20 believed alive. The text says more than **63,000** Palestinians have been killed, over 17,000 of them children according to UNICEF (RC-B10-0372/2025, recitals B and D).\n- It calls for an immediate and permanent ceasefire, the immediate and unconditional release of all Israeli hostages, Red Cross access to them, and further EU sanctions on Hamas (RC-B10-0372/2025, paras. 5 and 6).\n- It strongly condemns the Israeli government's obstruction of aid, 'which has caused a man-made famine in northern Gaza', citing a famine alert by the IPC food-security system backed by the FAO, WFP and UNICEF; it asks for all crossings to open and UNRWA's mandate and funding to be restored with strong oversight (RC-B10-0372/2025, paras. 2 and 3).\n- It reaffirms Israel's right to self-defence in line with international law, while saying that right 'cannot justify indiscriminate military action in Gaza', and condemns Hamas's use of civilians as human shields (RC-B10-0372/2025, paras. 7 and 9).\n- It supports the Commission President's plan to put EU bilateral support to Israel on hold and her proposal for a **partial suspension** of the EU-Israel Association Agreement on trade-related matters, and calls for sanctions on ministers **Bezalel Smotrich** and **Itamar Ben-Gvir** (RC-B10-0372/2025, paras. 22 and 25).\n- It backs a two-state solution on the 1967 borders, total demilitarisation of Gaza, exclusion of Hamas from governance, a reformed Palestinian Authority as the only governing force in Gaza, and asks member states to consider recognising the State of Palestine (RC-B10-0372/2025, paras. 26, 28 and 30).\n- It asks that the Commission's proposed **EUR 1.6 billion** support programme for the Palestinian Authority and Gaza have strict oversight and conditions so EU money does not support terrorism or incitement (RC-B10-0372/2025, para. 18).", "deep_lectura": "**Analyst read** *(inference, not stated verbatim in the record)*\n- The text is a compromise that tries to hold both sides to account in one vote, so people who agree on the goal (peace, hostages home, aid in) can still split over the balance of pressure it puts on each side.\n- The concrete levers it names (trade terms, sanctions, recognition) are decided by the Commission and national governments, not by this vote; its weight is political.\n- Words like 'consider' recognising and 'partial' suspension leave room for different readings of how far the EU should go.", "proposed_by": "Joint motion tabled by MEPs on behalf of the S&D, Renew and Greens/EFA groups", "doc_ref": "2025/2852(RSP), RC-B10-0372/2025", "outcome": "approved", "source_url": "https://howtheyvote.eu/votes/179048", "curator_drop": false, "party_votes_canon": {"AT": "against", "BE": "for", "CZ": "against", "DK": "for", "EE": "for", "ES": "for", "FI": "for", "HR": "for", "HU": "against", "IE": "for", "LT": "for", "LU": "for", "MT": "for", "NL": "for", "PT": "for", "RO": "against", "SE": "for", "SI": "for", "SK": "for"}, "tally": {"for": 305, "against": 151, "abstain": 122}}, {"id": "EP-2025-veggie-burger-names", "date": "2025-10-08", "session_code": "EP_10", "point": null, "organ": "European Parliament", "type": "Amendment", "topic": "Food labels", "headline": "Ban plant-based foods from using meat names such as burger, sausage and steak.", "title": "Strengthening of the position of farmers in the food supply chain", "raw_outcome": "Strengthening of the position of farmers in the food supply chain", "source_brief": "A change added to a law about farmers' bargaining power would reserve meat words for products that contain meat. A tofu burger or a veggie sausage would need a new name on the pack.\n\n- **Names on the list:** steak, escalope, sausage, burger, hamburger, even **egg yolk** and **egg white**, plus poultry cut names.\n- **Not just plants:** meat grown from cells in a lab is **excluded** from the names too.\n- **The argument for it:** meat words carry value built by livestock farmers, and shoppers should know what is in the pack.\n- **The handle:** if you think a 'veggie burger' misleads nobody and the market should decide, this is red tape that helps one industry against another; if you think farm products deserve protected names, like 'milk' and 'cheese' already have, this closes a gap.", "deep_facts": "- The amendment adds a new part on 'meat, meat products and meat preparations' to Annex VIII of the EU's farm market rules, Regulation (EU) No 1308/2013 (Amendment 113, report A10-0161/2025).\n- 'Meat' is defined as the edible parts of listed animals, including blood; meat-related names currently used for meat and meat cuts are reserved 'exclusively for the edible parts of the animals' (Amendment 113, point 1).\n- Names currently used for meat products and preparations are reserved for products containing meat; examples listed: **steak, escalope, sausage, burger, hamburger, egg yolk, egg white** (Amendment 113, point 3).\n- Poultry product and cut names defined in Regulation (EC) No 543/2008 are reserved for poultry meat, and the names may not be used for any other product, **including cell-cultured products** (Amendment 113, points 4 and 5).\n- The wider law aims to strengthen farmers' position against buyers after the early-2024 farmer protests: written contracts, clearer rules for 'fair' and 'short supply chain' labels, stronger producer organisations (report A10-0161/2025, explanatory statement, rapporteur Céline Imart).\n- In October 2024 the EU Court of Justice ruled that a member state cannot ban plant-based products from using meat terms unless the EU or that state has set a legal name for the product (Court of Justice, case C-438/23, 4 Oct 2024).", "deep_lectura": "**Analyst read** *(inference, not stated verbatim in the record)*\n- The ban rides on a law about farmers' income, which ties a labelling fight to a cause with broad sympathy; the question of what shoppers actually understand is not tested anywhere in the text.\n- Naming lab-grown meat alongside plant-based food suggests the target is future competition to livestock as much as today's veggie aisle.\n- Dairy words ('milk', 'butter') are already reserved in EU law, so supporters see this as consistency; opponents see a precedent for incumbents to fence off everyday words.", "proposed_by": "Committee on Agriculture and Rural Development (rapporteur Céline Imart)", "doc_ref": "2024/0319(COD), A10-0161/2025, Am 113", "outcome": "approved", "source_url": "https://howtheyvote.eu/votes/179529", "curator_drop": false, "party_votes_canon": {"BE": "against", "BG": "for", "CY": "for", "CZ": "for", "DE": "against", "DK": "against", "EE": "against", "ES": "for", "FI": "against", "FR": "for", "GR": "for", "HU": "for", "IE": "against", "IT": "for", "LT": "for", "LU": "against", "LV": "for", "MT": "against", "NL": "against", "PL": "for", "PT": "for", "RO": "for", "SE": "against", "SI": "for"}, "tally": {"for": 355, "against": 247, "abstain": 30}}, {"id": "EP-2026-mercosur-court", "date": "2026-01-21", "session_code": "EP_10", "point": null, "organ": "European Parliament", "type": "Resolution", "topic": "Trade", "headline": "Pause the EU-Mercosur trade deal until the EU's top court checks it is legal.", "title": "Request for opinion from the Court of Justice on the compatibility with the Treaties of the proposed EU-Mercosur Partnership Agreement (EMPA) and Interim Trade Agreement (ITA)", "raw_outcome": "Request for opinion from the Court of Justice on the compatibility with the Treaties of the proposed EU-Mercosur Partnership Agreement (EMPA) and Interim Trade Agreement (ITA)", "source_brief": "After more than two decades of talks, the EU has signed a trade deal with Argentina, Brazil, Paraguay and Uruguay, creating a free-trade area of **over 700 million people**. Parliament still has to give its consent. This vote is not yes or no to the deal: it asks the EU's top court to check its legality first, and Parliament's approval waits until the Court answers.\n\n- **The legal worries:** the deal was split in two, so the trade part may skip national parliaments; a 'rebalancing' clause could let Mercosur countries claim compensation for future EU rules that hurt their exports; and the deal may weaken the EU's 'better safe than sorry' rule on health and the environment.\n- **The wait:** Court opinions typically take **more than a year**.\n- **Who's watching:** farmers fear cheaper food made to lower standards; exporters of cars, machinery and wine want the new markets opened.\n- **The handle:** if you think a deal this big must be legally watertight before it binds Europe, and farmers deserve that check, ask the Court; if you see it as a delaying tactic that costs Europe trade and allies while rivals move in, vote against.", "deep_facts": "- The resolution asks the Court of Justice for an opinion on whether the EU-Mercosur Partnership Agreement (EMPA) and the Interim Trade Agreement (iTA) are compatible with the EU Treaties, under the Treaty procedure (Art. 218(11) TFEU) that lets EU institutions seek such opinions (EP press release, 21 Jan 2026; Real Instituto Elcano).\n- Parliament keeps examining the texts, and will vote to grant or withhold consent only after the Court's opinion (EP press release, 21 Jan 2026).\n- Mercosur partners: Argentina, Brazil, Paraguay and Uruguay; the agreement was signed on 17 January 2026 after more than two decades of negotiation and would create a free-trade area of over 700 million people (Euronews, 21 Jan 2026; HowTheyVote 183884).\n- The resolution's concerns: splitting the deal into the EMPA and the ITA may breach Art. 218(2) and (4) TFEU and keep national parliaments from having their say; the rebalancing mechanism, which lets a party seek compensation for the other side's rules even when they break no clause of the deal, may clash with the Treaties and the Charter; and the deal may weaken the precautionary principle, including by letting an arbitration panel judge how the EU applies it (resolution B10-0060/2026, paras 1 to 3).\n- The EMPA needs unanimity in the Council, Parliament's consent and ratification by all 27 member states; the ITA covers only EU-exclusive matters and needs only a qualified majority in the Council plus Parliament's consent (Legislative Observatory summary, 2026/2560(RSP)).\n- Court opinion procedures typically last more than a year, though an expedited procedure is possible (Real Instituto Elcano; Euronews).\n- The Commission can still apply the trade part provisionally if member states endorse it, even while the Court reviews (Euronews, 21 Jan 2026).", "deep_lectura": "**Analyst read** *(inference, not stated verbatim in the record)*\n- A court referral lets MEPs slow the deal without formally voting it down, which suits those who oppose it but prefer not to be seen rejecting trade outright.\n- If the trade part is applied provisionally anyway, the referral may delay Parliament's say more than the deal itself, shifting the fight to who decides EU trade policy.\n- The split cuts across usual lines: it follows national farm interests and trade exposure more than left and right.", "proposed_by": "Group of MEPs (motion for a resolution B10-0060/2026)", "doc_ref": "2026/2560(RSP), B10-0060/2026", "outcome": "approved", "source_url": "https://howtheyvote.eu/votes/183884", "curator_drop": false, "party_votes_canon": {"AT": "against", "BE": "for", "BG": "against", "CY": "for", "DE": "against", "DK": "against", "EE": "against", "ES": "against", "FI": "against", "FR": "for", "GR": "for", "HR": "against", "HU": "for", "IE": "for", "IT": "against", "LT": "against", "LU": "against", "LV": "against", "MT": "against", "NL": "against", "PL": "for", "PT": "against", "RO": "for", "SE": "against", "SI": "for", "SK": "for"}, "tally": {"for": 334, "against": 324, "abstain": 11}}, {"id": "EP-2026-ukraine-90bn-loan", "date": "2026-02-11", "session_code": "EP_10", "point": null, "organ": "European Parliament", "type": "Regulation", "topic": "Ukraine aid", "headline": "Lend Ukraine €90 billion in joint EU borrowing, repaid once Russia pays war reparations.", "title": "Regulation implementing enhanced cooperation on the establishment of the Ukraine Support Loan for 2026 and 2027", "raw_outcome": "Regulation implementing enhanced cooperation on the establishment of the Ukraine Support Loan for 2026 and 2027", "source_brief": "The EU would borrow **€90 billion** on the markets and lend it to Ukraine for 2026 and 2027. Ukraine repays the loan only once Russia pays it war reparations; until then, the interest is paid from the EU budget.\n\n- **Where it goes:** **€60 billion** for Ukraine's defence and weapons, bought in principle from Ukrainian and European industry; **€30 billion** to keep the state running.\n- **What it costs the EU:** interest estimated at about **€1 billion** in 2027 and about **€3 billion a year** from 2028.\n- **The strings:** money depends on democracy, rule of law, minority rights and fighting corruption; Czechia, Hungary and Slovakia opted out.\n- **The handle:** if Ukraine's defence is Europe's own security, sharing the bill is cheap insurance; if you think taxpayers are taking on joint debt for a loan that may never be repaid, this is a blank cheque.", "deep_facts": "- The Ukraine Support Loan provides **€90 billion** for 2026 and 2027: **€30 billion** in macro-financial assistance or budget support through the Ukraine Facility and **€60 billion** for defence capabilities and military procurement (EP press release, 11 Feb 2026; OEIL summary).\n- It is financed by common EU borrowing on capital markets, guaranteed by the headroom of the EU long-term budget; debt-servicing costs are covered by annual EU budgets, estimated at about **€1 billion** for 2027 and about **€3 billion** per year from 2028 (EP press release, 11 Feb 2026).\n- Ukraine is liable for repaying the principal once it receives war reparations from Russia (EP press release, 11 Feb 2026).\n- Defence purchases come in principle from Ukrainian, EU and EEA/EFTA industry; other countries only where nothing is available, under conditions including a fair contribution to borrowing costs (OEIL summary).\n- Aid depends on Ukraine upholding democratic mechanisms, the rule of law, human rights including minority rights, and fighting corruption; the Council approves the amount based on a Ukrainian financing strategy assessed by the Commission (OEIL summary).\n- Agreed by EU leaders on 18 December 2025; the €90 billion is meant to cover two-thirds of Ukraine's estimated needs; as Czechia, Hungary and Slovakia opted out, it runs as enhanced cooperation among the willing countries (EP press release, 11 Feb 2026).", "deep_lectura": "**Analyst read** *(inference, not stated verbatim in the record)*\n- 'Repaid once Russia pays reparations' ties repayment to an event no one controls, so in practice the loan may work like a grant funded by EU debt.\n- Enhanced cooperation sets a precedent: a group of countries can borrow in the EU's name without unanimity, a route that could be reused for other shared spending.\n- The buy-European rule makes this an industrial policy as well as aid: much of the €60 billion would flow to European arms makers.", "proposed_by": "European Commission", "doc_ref": "2026/0008(COD), C10-0005/2026", "outcome": "approved", "source_url": "https://howtheyvote.eu/votes/184699", "curator_drop": false, "party_votes_canon": {"AT": "for", "BE": "for", "BG": "for", "CZ": "for", "DE": "for", "DK": "for", "EE": "for", "ES": "for", "FI": "for", "HR": "for", "HU": "against", "IE": "for", "IT": "for", "LT": "for", "LU": "for", "LV": "for", "MT": "abstain", "NL": "for", "PL": "for", "PT": "for", "RO": "for", "SE": "for", "SI": "for", "SK": "against"}, "tally": {"for": 458, "against": 140, "abstain": 44}}, {"id": "EP-2026-chat-control-extension", "date": "2026-03-26", "session_code": "EP_10", "point": null, "organ": "European Parliament", "type": "Regulation", "topic": "Privacy", "headline": "Extend the temporary EU rule letting messaging apps scan private messages for child abuse images.", "title": "Proposal for a regulation of the European Parliament and of the Council amending Regulation (EU) 2021/1232 as regards the extension of its period of application", "raw_outcome": "Proposal for a regulation of the European Parliament and of the Council amending Regulation (EU) 2021/1232 as regards the extension of its period of application", "source_brief": "Since 2021 a temporary EU rule has let chat and email services voluntarily scan private messages for child sexual abuse material, a carve-out from Europe's privacy law. It runs out after **3 April 2026**; voting against lets it lapse, which ends the legal basis for that voluntary scanning.\n\n- **What FOR keeps:** providers may go on checking messages for abuse images and grooming while a permanent law is still being negotiated.\n- **What it is not:** scanning stays **voluntary**; nobody is forced to scan, and the permanent law is a separate fight.\n- **The version on the table:** Parliament's own position ran it only to **August 2027**, with a narrower scope than the Commission first proposed.\n- **The handle:** if protecting children from abuse online outweighs everything, a gap in detection is the worst outcome; if private messages should stay private by default, a 'temporary' exception renewed again and again is how mass scanning becomes normal.", "deep_facts": "- Regulation (EU) 2021/1232 is a temporary exception to the ePrivacy Directive's confidentiality rules, letting communication services voluntarily detect child sexual abuse online in private communications (EP press release, 26 Mar 2026).\n- The exception was already extended in 2024; without a new extension it expires after **3 April 2026** (EP press release, 26 Mar 2026).\n- The stated purpose of the extension is to keep the temporary measures in place while negotiations continue on a long-term law to prevent and combat child sexual abuse online; Parliament has been ready to negotiate that law since November 2023 and Council adopted its position in November 2025 (EP press release, 26 Mar 2026).\n- Parliament's position of 11 March 2026 favoured a shorter extension, **until August 2027**, and a narrower scope than the Commission proposal, to keep the measures proportional and targeted; talks with Council did not reach an agreement (EP press release, 26 Mar 2026).\n- The rapporteur declared input from European Digital Rights, CCIA, Doteurope, Google, Microsoft, Snapchat and X/Twitter (report A10-0040/2026, declaration of input).", "deep_lectura": "**Analyst read** *(inference, not stated verbatim in the record)*\n- The vote is less about scanning itself than about leverage: letting the stopgap lapse raises the pressure on governments to agree the permanent law, while renewing it takes the pressure off.\n- Both sides claim child protection and both claim proportionality, which is why the split does not follow usual left-right lines.\n- Big platforms appear on the lobbying list; a lapse moves the legal risk of scanning onto them, which may change what they do regardless of the law.", "proposed_by": "European Commission (rapporteur Birgit Sippel)", "doc_ref": "2025/0429(COD), COM(2025)0797, A10-0040/2026", "outcome": "rejected", "source_url": "https://howtheyvote.eu/votes/189270", "curator_drop": false, "party_votes_canon": {"AT": "against", "CY": "against", "DE": "against", "DK": "against", "EE": "against", "FI": "against", "FR": "for", "HR": "against", "HU": "for", "IE": "for", "LT": "against", "LU": "against", "LV": "against", "MT": "for", "NL": "against", "PL": "for", "PT": "against", "SI": "against"}, "tally": {"for": 228, "against": 311, "abstain": 92}}]};
